-- =====================================================================
-- GLOBAL RECIPROCAL COLLEGES (GRC)
-- Three-Role Academic Grading System — Complete Schema & Demo Dataset
-- Database: grc_grading
-- =====================================================================

CREATE DATABASE IF NOT EXISTS `grc_grading`
  CHARACTER SET utf8mb4
  COLLATE utf8mb4_unicode_ci;

USE `grc_grading`;

CREATE TABLE IF NOT EXISTS `professors` (
  `id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `employee_id` VARCHAR(50) NOT NULL UNIQUE,
  `username` VARCHAR(50) NOT NULL UNIQUE,
  `full_name` VARCHAR(150) NOT NULL,
  `email` VARCHAR(190) NOT NULL UNIQUE,
  `password_hash` VARCHAR(255) NOT NULL,
  `department` VARCHAR(120) NOT NULL DEFAULT 'College of Computer Studies',
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `students` (
  `id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `student_no` VARCHAR(50) NOT NULL UNIQUE,
  `username` VARCHAR(50) NOT NULL UNIQUE,
  `first_name` VARCHAR(100) NOT NULL,
  `last_name` VARCHAR(100) NOT NULL,
  `email` VARCHAR(150) NULL,
  `course` VARCHAR(100) NOT NULL DEFAULT 'BS Information Technology',
  `year_level` VARCHAR(30) NOT NULL DEFAULT '3rd Year',
  `password_hash` VARCHAR(255) NOT NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `subjects` (
  `id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `professor_id` INT UNSIGNED NOT NULL,
  `subject_code` VARCHAR(50) NOT NULL,
  `subject_title` VARCHAR(150) NOT NULL,
  `section` VARCHAR(50) NOT NULL,
  `units` INT NOT NULL DEFAULT 3,
  `school_year` VARCHAR(20) NOT NULL,
  `semester` ENUM('1st Semester', '2nd Semester', 'Summer') NOT NULL DEFAULT '1st Semester',
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  INDEX `idx_subject_professor` (`professor_id`),
  CONSTRAINT `fk_subjects_professor` FOREIGN KEY (`professor_id`)
    REFERENCES `professors` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `enrollments` (
  `id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `professor_id` INT UNSIGNED NOT NULL,
  `subject_id` INT UNSIGNED NOT NULL,
  `student_id` INT UNSIGNED NOT NULL,
  `enrolled_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY `uq_subject_student` (`subject_id`, `student_id`),
  INDEX `idx_enrollment_professor` (`professor_id`),
  INDEX `idx_enrollment_student` (`student_id`),
  CONSTRAINT `fk_enrollments_professor` FOREIGN KEY (`professor_id`)
    REFERENCES `professors` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_enrollments_subject` FOREIGN KEY (`subject_id`)
    REFERENCES `subjects` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_enrollments_student` FOREIGN KEY (`student_id`)
    REFERENCES `students` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `grades` (
  `id` INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
  `enrollment_id` INT UNSIGNED NOT NULL UNIQUE,
  `mid_lec_attendance` DECIMAL(5,2) NULL DEFAULT NULL,
  `mid_lec_recitation` DECIMAL(5,2) NULL DEFAULT NULL,
  `mid_lec_assignment` DECIMAL(5,2) NULL DEFAULT NULL,
  `mid_lec_quizzes` DECIMAL(5,2) NULL DEFAULT NULL,
  `mid_lec_prelim_exam` DECIMAL(5,2) NULL DEFAULT NULL,
  `mid_lec_midterm_exam` DECIMAL(5,2) NULL DEFAULT NULL,
  `mid_lab_attendance` DECIMAL(5,2) NULL DEFAULT NULL,
  `mid_lab_recitation` DECIMAL(5,2) NULL DEFAULT NULL,
  `mid_lab_assignment` DECIMAL(5,2) NULL DEFAULT NULL,
  `mid_lab_quizzes` DECIMAL(5,2) NULL DEFAULT NULL,
  `mid_lab_prelim_exam` DECIMAL(5,2) NULL DEFAULT NULL,
  `mid_lab_midterm_exam` DECIMAL(5,2) NULL DEFAULT NULL,
  `fnl_lec_attendance` DECIMAL(5,2) NULL DEFAULT NULL,
  `fnl_lec_recitation` DECIMAL(5,2) NULL DEFAULT NULL,
  `fnl_lec_assignment` DECIMAL(5,2) NULL DEFAULT NULL,
  `fnl_lec_quizzes` DECIMAL(5,2) NULL DEFAULT NULL,
  `fnl_lec_final_exam` DECIMAL(5,2) NULL DEFAULT NULL,
  `fnl_lab_attendance` DECIMAL(5,2) NULL DEFAULT NULL,
  `fnl_lab_recitation` DECIMAL(5,2) NULL DEFAULT NULL,
  `fnl_lab_assignment` DECIMAL(5,2) NULL DEFAULT NULL,
  `fnl_lab_quizzes` DECIMAL(5,2) NULL DEFAULT NULL,
  `fnl_lab_final_exam` DECIMAL(5,2) NULL DEFAULT NULL,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT `fk_grades_enrollment` FOREIGN KEY (`enrollment_id`)
    REFERENCES `enrollments` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `classbook_admins` (
  `id` INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,
  `username` VARCHAR(80) NOT NULL UNIQUE,
  `full_name` VARCHAR(150) NOT NULL,
  `password_hash` VARCHAR(255) NOT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `classbook_access` (
  `role` VARCHAR(20) NOT NULL,
  `account_id` INT UNSIGNED NOT NULL,
  `status` VARCHAR(20) NOT NULL DEFAULT 'active',
  PRIMARY KEY(`role`,`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `classbook_tokens` (
  `id` BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,
  `role` VARCHAR(20) NOT NULL,
  `account_id` INT UNSIGNED NOT NULL,
  `token_hash` CHAR(64) NOT NULL UNIQUE,
  `expires_at` DATETIME NOT NULL,
  `used_at` DATETIME NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `classbook_settings` (
  `subject_id` INT UNSIGNED PRIMARY KEY,
  `revision` INT UNSIGNED NOT NULL DEFAULT 1,
  `state` VARCHAR(20) NOT NULL DEFAULT 'draft',
  `archived` TINYINT NOT NULL DEFAULT 0,
  `late_points` DECIMAL(8,2) NOT NULL DEFAULT 3,
  `absent_points` DECIMAL(8,2) NOT NULL DEFAULT 0,
  `excused_mode` VARCHAR(20) NOT NULL DEFAULT 'makeup',
  `online_full_minutes` DECIMAL(10,2) NULL,
  `online_partial_minutes` DECIMAL(10,2) NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  `grading_model` VARCHAR(30) NOT NULL DEFAULT 'legacy_components',
  FOREIGN KEY(`subject_id`) REFERENCES `subjects`(`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `classbook_members` (
  `enrollment_id` INT UNSIGNED PRIMARY KEY,
  `status` VARCHAR(20) NOT NULL DEFAULT 'active',
  `starts_on` DATE NOT NULL,
  `reason` VARCHAR(500) NOT NULL DEFAULT '',
  FOREIGN KEY(`enrollment_id`) REFERENCES `enrollments`(`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `classbook_criteria` (
  `id` INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,
  `subject_id` INT UNSIGNED NOT NULL,
  `group_key` VARCHAR(20) NOT NULL,
  `name` VARCHAR(100) NOT NULL,
  `kind` VARCHAR(20) NOT NULL,
  `weight` DECIMAL(7,2) NOT NULL,
  `aggregation` VARCHAR(20) NOT NULL DEFAULT 'pooled',
  `excused_mode` VARCHAR(20) NOT NULL DEFAULT 'makeup',
  `exam_key` VARCHAR(20) NULL,
  UNIQUE KEY `criterion_name`(`subject_id`,`group_key`,`name`),
  FOREIGN KEY(`subject_id`) REFERENCES `subjects`(`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `classbook_activities` (
  `id` INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,
  `criterion_id` INT UNSIGNED NOT NULL,
  `title` VARCHAR(150) NOT NULL,
  `maximum` DECIMAL(12,2) NOT NULL,
  `due_on` DATE NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(`criterion_id`) REFERENCES `classbook_criteria`(`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `classbook_scores` (
  `activity_id` INT UNSIGNED NOT NULL,
  `enrollment_id` INT UNSIGNED NOT NULL,
  `status` VARCHAR(20) NOT NULL DEFAULT 'not_graded',
  `earned` DECIMAL(12,2) NULL,
  PRIMARY KEY(`activity_id`,`enrollment_id`),
  FOREIGN KEY(`activity_id`) REFERENCES `classbook_activities`(`id`) ON DELETE RESTRICT,
  FOREIGN KEY(`enrollment_id`) REFERENCES `enrollments`(`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `classbook_meetings` (
  `id` INT UNSIGNED PRIMARY KEY AUTO_INCREMENT,
  `criterion_id` INT UNSIGNED NOT NULL,
  `meeting_date` DATE NOT NULL,
  `title` VARCHAR(150) NOT NULL,
  `source_key` CHAR(64) NULL UNIQUE,
  `source_json` LONGTEXT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(`criterion_id`) REFERENCES `classbook_criteria`(`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `classbook_attendance` (
  `meeting_id` INT UNSIGNED NOT NULL,
  `enrollment_id` INT UNSIGNED NOT NULL,
  `status` VARCHAR(20) NOT NULL,
  `duration_seconds` DECIMAL(12,2) NULL,
  `source_identity` VARCHAR(255) NULL,
  PRIMARY KEY(`meeting_id`,`enrollment_id`),
  FOREIGN KEY(`meeting_id`) REFERENCES `classbook_meetings`(`id`) ON DELETE RESTRICT,
  FOREIGN KEY(`enrollment_id`) REFERENCES `enrollments`(`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `classbook_imports` (
  `id` BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,
  `subject_id` INT UNSIGNED NOT NULL,
  `fingerprint` CHAR(64) NOT NULL,
  `meeting_id` INT UNSIGNED NOT NULL,
  `actor_id` INT UNSIGNED NOT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  UNIQUE KEY `once_per_class`(`subject_id`,`fingerprint`),
  FOREIGN KEY(`subject_id`) REFERENCES `subjects`(`id`) ON DELETE RESTRICT,
  FOREIGN KEY(`meeting_id`) REFERENCES `classbook_meetings`(`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `classbook_releases` (
  `id` BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,
  `subject_id` INT UNSIGNED NOT NULL,
  `revision` INT UNSIGNED NOT NULL,
  `snapshot_json` LONGTEXT NOT NULL,
  `actor_id` INT UNSIGNED NOT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY(`subject_id`) REFERENCES `subjects`(`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `classbook_audit` (
  `id` BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT,
  `actor_role` VARCHAR(20) NOT NULL,
  `actor_id` INT UNSIGNED NOT NULL,
  `subject_id` INT UNSIGNED NULL,
  `action` VARCHAR(80) NOT NULL,
  `detail_json` LONGTEXT NOT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `classbook_policies` (
  `subject_id` INT UNSIGNED PRIMARY KEY,
  `lecture_percent` DECIMAL(5,2) NOT NULL DEFAULT 65,
  `midterm_percent` DECIMAL(5,2) NOT NULL DEFAULT 50,
  `passing_percent` DECIMAL(5,2) NOT NULL DEFAULT 75,
  `policy_label` VARCHAR(150) NOT NULL DEFAULT 'Provisional defaults',
  `conversion_json` TEXT NULL,
  FOREIGN KEY(`subject_id`) REFERENCES `subjects`(`id`) ON DELETE RESTRICT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `classbook_account_meta` (
  `role` VARCHAR(20) NOT NULL,
  `account_id` INT UNSIGNED NOT NULL,
  `revision` INT UNSIGNED NOT NULL DEFAULT 1,
  `public_id` VARCHAR(32) NULL UNIQUE,
  PRIMARY KEY(`role`,`account_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `classbook_login_limits` (
  `bucket` CHAR(64) PRIMARY KEY,
  `attempts` INT UNSIGNED NOT NULL DEFAULT 0,
  `window_started` DATETIME NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS `classbook_migrations` (
  `version` INT PRIMARY KEY,
  `applied_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


